-- =====================================================================
-- Engram · PHASE 0 · P0-P1 / P0-P2 vector-index verification probe
-- Role: [PLUMBER]
-- Target: CockroachDB Cloud **Basic** cluster `engram-memory`
--
-- Run top to bottom. Paste the FULL transcript into
-- docs/phase0-verification.md. Steps 5 and 6 are the exit gate:
--   step 5 MUST show a vector index scan
--   step 6 MUST NOT  (it is the negative control for CLAUDE.md inv. #3)
--
-- Connect:
--   cockroach sql --url "$ENGRAM_MEMORY_DSN" -f db/phase0_vector_probe.sql --echo-sql
-- or paste into the Cloud Console SQL shell.
-- =====================================================================


-- ---------------------------------------------------------------------
-- STEP 1 — enable the feature gate (CLAUDE.md invariant #1)
-- If this errors with "unknown cluster setting", vector indexes are not
-- available on this cluster version -> STOP and take the Phase 0
-- fallback (brute-force cosine over a bounded candidate set).
-- ---------------------------------------------------------------------
SET CLUSTER SETTING feature.vector_index.enabled = true;
SHOW CLUSTER SETTING feature.vector_index.enabled;   -- expect: true

SELECT version();                                     -- record the build


-- ---------------------------------------------------------------------
-- STEP 2 — probe table. NO INDEX YET.
-- CLAUDE.md invariant #1: seed rows BEFORE creating the vector index.
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS vec_probe;

CREATE TABLE vec_probe (
    id        INT8 PRIMARY KEY,
    scope_id  STRING    NOT NULL,     -- the mandatory index prefix column
    label     STRING,
    embedding VECTOR(1024)            -- Titan Text Embeddings V2 @ 1024 dims
);


-- ---------------------------------------------------------------------
-- STEP 3 — seed 400 rows across 2 scopes, deterministically.
-- Correlated on g.i so every row is a distinct vector.
-- ---------------------------------------------------------------------
INSERT INTO vec_probe (id, scope_id, label, embedding)
SELECT
    g.i,
    CASE WHEN g.i % 2 = 0 THEN 'org-alpha' ELSE 'org-beta' END,
    'seed-' || g.i::STRING,
    (
      '[' ||
      (SELECT string_agg(
                (sin((g.i::FLOAT8 * 0.013) + (d.k::FLOAT8 * 0.7)) * 0.5 + cos(d.k::FLOAT8 * 0.11) * 0.5)::STRING,
                ',' ORDER BY d.k)
         FROM generate_series(1, 1024) AS d(k))
      || ']'
    )::VECTOR(1024)
FROM generate_series(1, 400) AS g(i);

SELECT scope_id, count(*) AS rows FROM vec_probe GROUP BY scope_id ORDER BY scope_id;
-- expect: org-alpha 200 / org-beta 200


-- ---------------------------------------------------------------------
-- STEP 4 — create the C-SPANN index AFTER seeding.
-- CLAUDE.md invariant #2 - exact shape, do not paraphrase.
-- ---------------------------------------------------------------------
CREATE VECTOR INDEX vec_probe_scope_cos
    ON vec_probe (scope_id, embedding vector_cosine_ops)
    WITH (min_partition_size = 16, max_partition_size = 128);

SHOW INDEXES FROM vec_probe;
SHOW CREATE TABLE vec_probe;   -- paste this: it is the proof artifact


-- ---------------------------------------------------------------------
-- STEP 5 — THE EXIT GATE. scope_id equality-constrained + <=> + LIMIT.
-- EXPLAIN output MUST mention a vector index / vector search on
-- vec_probe_scope_cos. If it says "full scan" here, the gate FAILS.
-- ---------------------------------------------------------------------
